@namespace sv_2e14e2ab30644ace973c39d85fe178bd.Components.Application

<nav aria-label="Application steps" class="mb-4">
    <ol class="d-flex list-unstyled justify-content-between step-indicator">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var step = i;
            var isCompleted = CompletedSteps.Contains(step);
            var isCurrent = step == CurrentStep;
            var isFuture = !isCompleted && !isCurrent;

            <li class="text-center flex-fill position-relative @(isCurrent ? "step-current" : isCompleted ? "step-completed" : "step-future")"
                role="listitem">
                @if (isCompleted)
                {
                    <button class="btn btn-link text-decoration-none p-0 w-100" @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <div class="step-circle bg-success text-white mx-auto">✓</div>
                        <div class="small mt-1 text-success fw-semibold">@StepNames[step]</div>
                    </button>
                }
                else
                {
                    <div>
                        <div class="step-circle mx-auto @(isCurrent ? "bg-primary text-white" : "bg-light text-muted border")">
                            @(step + 1)
                        </div>
                        <div class="small mt-1 @(isCurrent ? "fw-semibold text-primary" : "text-muted")">@StepNames[step]</div>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

<style>
    .step-circle {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 0.85rem;
        font-weight: 600;
    }
</style>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

