@namespace sv_2e14e2ab30644ace973c39d85fe178bd.Components.Application
@using sv_2e14e2ab30644ace973c39d85fe178bd.Models

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-2">
    <textarea class="form-control" rows="10"
              @bind="CoverLetter"
              @bind:event="oninput"
              maxlength="@MaxLength"
              placeholder="Write your cover letter here…"></textarea>
</div>

<div class="text-muted small mb-3 text-end">
    @(CoverLetter?.Length ?? 0) / @MaxLength characters
</div>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
</div>

@code {
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;

    private async Task HandleNext()
    {
        await CoverLetterChanged.InvokeAsync(CoverLetter);
        await OnNext.InvokeAsync();
    }
}

@namespace sv_2e14e2ab30644ace973c39d85fe178bd.Components.Application
@using sv_2e14e2ab30644ace973c39d85fe178bd.Models

@if (IsSubmitted)
{
    <div class="text-center py-5">
        <div class="mb-3">
            <span class="display-1 text-success">✓</span>
        </div>
        <h3 class="text-success">Application Submitted!</h3>
        <p class="lead">Your application ID is <strong>#@ApplicationId</strong></p>
        <p class="text-muted">We'll review your application and get back to you soon.</p>
    </div>
}
else
{
    <h4 class="mb-3">Review & Submit</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <!-- Personal Info -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Personal Information</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6"><strong>Name:</strong> @Model.Personal.FullName</div>
                <div class="col-md-6"><strong>Email:</strong> @Model.Personal.Email</div>
                <div class="col-md-6"><strong>Phone:</strong> @Model.Personal.Phone</div>
                <div class="col-md-6"><strong>Address:</strong> @Model.Personal.Address</div>
            </div>
        </div>
    </div>

    <!-- Work History -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Work History</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var entry in Model.WorkEntries)
            {
                <div class="mb-3 pb-2 border-bottom last-child-no-border">
                    <div><strong>@entry.Title</strong> at @entry.Company</div>
                    <div class="text-muted small">
                        @(entry.StartDate?.ToString("MMM yyyy") ?? "N/A") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <div class="mt-1">@entry.Description</div>
                    }
                </div>
            }
        </div>
    </div>

    <!-- References -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>References</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var r in Model.References)
            {
                <div class="mb-2">
                    <strong>@r.Name</strong> — @r.Relationship
                    <div class="text-muted small">@r.Email · @r.Phone</div>
                </div>
            }
        </div>
    </div>

    <!-- Cover Letter -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Cover Letter</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
        </div>
        <div class="card-body">
            <p style="white-space: pre-wrap;">@Model.CoverLetter</p>
        </div>
    </div>

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
        <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
                <text>Submitting…</text>
            }
            else
            {
                <text>Submit Application</text>
            }
        </button>
    </div>
}

@code {
    [Parameter, EditorRequired] public ApplicationFormModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }

    private async Task HandleSubmit() => await OnSubmit.InvokeAsync();
}

