@page "/apply"
@rendermode InteractiveServer
@using sv_2e14e2ab30644ace973c39d85fe178bd.Components.Application
@using sv_2e14e2ab30644ace973c39d85fe178bd.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   StepNames="stepNames"
                   OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep Model="form.Personal"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="NextStep" />
                break;
            case 1:
                <WorkHistoryStep Entries="form.WorkEntries"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 2:
                <ReferencesStep References="form.References"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;
            case 3:
                <CoverLetterStep @bind-CoverLetter="form.CoverLetter"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 4:
                <ReviewStep Model="form"
                            OnBack="PreviousStep"
                            OnEditStep="GoToStep"
                            OnSubmit="SubmitApplication"
                            IsSubmitting="isSubmitting"
                            IsSubmitted="isSubmitted"
                            ApplicationId="applicationId"
                            ErrorMessage="submitError" />
                break;
        }
    </div>
</div>

@code {
    private readonly ApplicationFormModel form = new();
    private int currentStep;
    private readonly HashSet<int> completedSteps = [];
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;
    private string? submitError;

    private static readonly IReadOnlyList<string> stepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        if (currentStep < stepNames.Count - 1)
            currentStep++;
    }

    private void PreviousStep()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
            currentStep = step;
    }

    private async Task SubmitApplication()
    {
        submitError = null;
        isSubmitting = true;

        try
        {
            var result = await ApplicationService.SubmitApplicationAsync(form.ToRecord());
            applicationId = result;
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

